#include <Servo.h>

Servo servo;

void setup() {
  servo.attach(9);
}

void loop() {
  for (int a = 0; a <= 180; a++) { servo.write(a); delay(10); }
  for (int a = 180; a >= 0; a--) { servo.write(a); delay(10); }
}

