void setup() {
  pinMode(2, INPUT); pinMode(3, INPUT); pinMode(4, INPUT_PULLUP);
  Serial.begin(9600);
}

int last = HIGH;
void loop() {
  int clk = digitalRead(2);
  if (clk != last && clk == LOW) Serial.println(digitalRead(3) != clk ? "right" : "left");
  last = clk;
}
